import json
import urllib.error
import urllib.request

# The old host `prices.internal` (endpoint /api/v1/price/<sku>, field "price")
# was retired. The pricing service now lives at pricing-v2.internal and exposes
# /api/v2/price/<sku>, returning {"sku": ..., "unit_price": ...} and requiring
# the X-Pricing-Key header.
BASE = "http://pricing-v2.internal:8081/api/v2/price"
PRICING_KEY = "pk-7f3a91"


def get_price(sku: str) -> float:
    req = urllib.request.Request(
        f"{BASE}/{sku}", headers={"X-Pricing-Key": PRICING_KEY}
    )
    with urllib.request.urlopen(req, timeout=5) as r:
        payload = json.load(r)
    # v2 exposes the unit price under "unit_price" (legacy v1 used "price").
    if "unit_price" in payload:
        return float(payload["unit_price"])
    return float(payload["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
